'use strict';
(function(root){const cache=new Map;function sprite(p,cell,slot,x,y,t,w=95,h=w,angle=0,alpha=1){const key=cell+'-'+slot;if(!cache.has(key)){const im=new Image;im.src='rpg-fx/bard/bard-'+key+'.svg';cache.set(key,im);}const im=cache.get(key);if(!im.complete||!im.naturalWidth)return;const frame=Math.min(7,Math.max(0,Math.floor(t*8)));p.save();p.globalAlpha*=alpha;p.translate(x,y);p.rotate(angle);p.imageSmoothingEnabled=false;p.drawImage(im,frame*256,0,256,256,-w/2,-h/2,w,h);p.restore();}
function draw(p,f,t){if(f.heroId!==6)return false;if(t<0||t>3.4)return true;const cell=f.cell||0,slot=f.slot||0,o=f.from||f,ox=o.x,oy=o.y-24,tx=f.x,ty=f.y-22,theta=Math.atan2(ty-oy,tx-ox),q=Math.min(1,t/.65),phase=!!f.phase;
if(phase){const size=/sword-final|meteor/.test(f.bardKind||'')?135:65;sprite(p,cell,slot,tx,ty,t,size,size,cell===5?theta:0);return true;}
if(cell===0){if(slot===0){sprite(p,0,0,ox+(tx-ox)*q,oy+(ty-oy)*q,t,65);}if(slot===1)sprite(p,0,1,ox,oy-12,t,110,125);if(slot===2)sprite(p,0,2,ox,oy-t*15,t,85,115);if(slot===3)sprite(p,0,3,ox+Math.cos(theta)*t*200,oy+Math.sin(theta)*t*200,t,150,180,theta);}
if(cell===1){if(slot===0){sprite(p,1,0,ox+(tx-ox)*q,oy+(ty-oy)*q,t,100,80,theta);}if(slot===1)sprite(p,1,1,ox+20,oy-20,t,150,85);if(slot===2)sprite(p,1,2,ox,oy+10,t,135,100);if(slot===3)for(let j=0;j<3;j++){const age=t-j*.18;if(age>=0)sprite(p,1,3,ox+Math.cos(theta)*age*210,oy+Math.sin(theta)*age*210,age,180,170,theta);}}
if(cell===2){if(slot===0)sprite(p,2,0,(ox+tx)/2,(oy+ty)/2,t,Math.max(120,Math.hypot(tx-ox,ty-oy)),100,theta);if(slot===1)sprite(p,2,1,ox,oy+15,t,185,120,t*2);if(slot===2)sprite(p,2,2,ox-20+t*15,oy+35,t,100,65);if(slot===3)sprite(p,2,3,ox,oy+20,t,270,180,t*1.5);}
if(cell===3){if(slot===0)for(let j=0;j<3;j++){const age=t-j*.16;if(age>=0)sprite(p,3,0,ox+(tx-ox)*Math.min(1,age/.45),oy+(ty-oy)*Math.min(1,age/.45),age,80,80,theta);}if(slot===1)sprite(p,3,1,ox,oy-25,t,115,150);if(slot===2)sprite(p,3,2,ox+Math.min(80,t*50),oy,t,160,95,0,.75);if(slot===3)sprite(p,3,3,tx,ty,t,220,200);}
if(cell===4){if(slot===0)sprite(p,4,0,tx,ty,t,80,105);if(slot===1){const rev=1-q;sprite(p,4,1,ox+(tx-ox)*rev,oy+(ty-oy)*rev,t,120,100,theta);}if(slot===2)sprite(p,4,2,ox,oy,t,200,130);if(slot===3)sprite(p,4,3,ox+40,oy-10,t,200,160);}
if(cell===5){if(slot===0)sprite(p,5,0,tx,ty,t,125,125,theta);if(slot===1)sprite(p,5,1,ox,oy-10,t,90,145);if(slot===2)sprite(p,5,2,ox-t*30,oy,t,130,100,theta);if(slot===3)sprite(p,5,3,tx,ty,t,190,170,t*.8);}
if(cell===6){if(slot===0)sprite(p,6,0,ox+(tx-ox)*q,oy+(ty-oy)*q,t,85,55,theta);if(slot===1)sprite(p,6,1,ox,oy+12,t,190,130);if(slot===2)sprite(p,6,2,tx,ty,t,240,170);if(slot===3)for(let j=0;j<3;j++){const age=t-j*.22;if(age>=0&&age<1)sprite(p,6,3,tx+(j-1)*45,ty-120+age*130,age,110,150);}}
return true;}
function state(p,g,time){const c=g.c,b=c?.bard;if(g.s.active!==6||!b)return;for(const star of b.orbit)sprite(p,6,0,star.x,star.y-16,time%1,40,40,star.angle);const nodes=b.links.map(id=>c.enemies.find(e=>e.id===id&&e.hp>0)).filter(Boolean);if(b.timers.links>0){for(let i=1;i<nodes.length;i++){const a=nodes[i-1],z=nodes[i],dx=z.x-a.x,dy=z.y-a.y,len=Math.hypot(dx,dy);p.save();p.translate(a.x,a.y-18);p.rotate(Math.atan2(dy,dx));p.fillStyle='#82cfff';p.globalAlpha=.65+Math.sin(time*5)*.15;p.fillRect(0,-2,len,4);p.fillStyle='#e8faff';p.fillRect(0,-.5,len,1);p.restore();}for(const node of nodes)sprite(p,6,0,node.x,node.y-18,time%1,32,32);}if(b.song&&b.timers.song>0)sprite(p,1,b.song==='bravery'?1:2,c.x,c.y-24,time%1,b.song==='bravery'?85:110,75,0,.35);for(const e of c.enemies){if(e.hp>0&&e.bardMark>0)sprite(p,6,0,e.x,e.y-60,time%1,24,24);if(e.hp>0&&e.statuses?.dirge&&g.h.cell===4)sprite(p,4,0,e.x,e.y-22,time%1,33,48);}
if(g.h.cell===3||g.h.cell===1||g.h.cell===4||g.h.cell===5){p.save();p.textAlign='center';p.font='bold 10px sans-serif';p.fillStyle=g.h.cell===4?'#dac0ef':'#ffe4a1';p.fillText(g.h.cell===3?'합주 '+b.ensemble+'/100':g.h.cell===1?'화음 '+b.chord+'/3':g.h.cell===4?'영혼 '+b.souls+'/6':'집중 '+b.focus+'/5',c.x,c.y-88);p.restore();}}
function preload(){for(let c=0;c<7;c++)for(let s=0;s<4;s++)sprite({save(){},restore(){},translate(){},rotate(){},drawImage(){},globalAlpha:1},c,s,0,0,0);}
root.RPG_BARD_FX={draw,state,sprite,preload};})(typeof window!=='undefined'?window:globalThis);
